import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.VWKgVqrc.js";const u=JSON.parse('{"title":"Agent 核心研究与竞品动态 · 2026-11-14","description":"","frontmatter":{"title":"Agent 核心研究与竞品动态 · 2026-11-14","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-14.md","filePath":"zh/runtime/daily-intelligence/2026-11-14.md","lastUpdated":null}'),n={name:"zh/runtime/daily-intelligence/2026-11-14.md"};function p(l,e,i,s,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_2026-11-14-·-agent-核心研究与竞品动态" tabindex="-1">2026-11-14 · Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-14-·-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-14 · Agent 核心研究与竞品动态&quot;">​</a></h1><p>本轮核心判断：企业治理正在补齐执行上下文、耐久证据与恢复结算；多 Agent 产品的竞争已延伸到并发启动、后台续跑与独立验收。29 项事实观察与 5 组研究分析如下，代码合入与正式发行分别标识。</p><h2 id="事实观察" tabindex="-1">事实观察 <a class="header-anchor" href="#事实观察" aria-label="Permalink to &quot;事实观察&quot;">​</a></h2><h3 id="o1-·-codex-完成通知前先持久化实时记录" tabindex="-1">O1 · Codex：完成通知前先持久化实时记录 <a class="header-anchor" href="#o1-·-codex-完成通知前先持久化实时记录" aria-label="Permalink to &quot;O1 · Codex：完成通知前先持久化实时记录&quot;">​</a></h3><p>2026-11-14T06:15:07Z · <strong>MERGED</strong> · main · <a href="https://github.com/openai/codex/pull/61473" target="_blank" rel="noreferrer">原始来源</a></p><p>记录首次观察时间，恢复 checkpoint 时保留时钟下限；完成通知前刷新记录及本地耐久性屏障。另 #61434 将被丢弃的待审批工具派发记为 Aborted 并补结束时间。中断状态改善证据闭合，不能证明动作没有副作用。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o2-·-codex-mcp-注册作用域贯穿调用与-oauth" tabindex="-1">O2 · Codex：MCP 注册作用域贯穿调用与 OAuth <a class="header-anchor" href="#o2-·-codex-mcp-注册作用域贯穿调用与-oauth" aria-label="Permalink to &quot;O2 · Codex：MCP 注册作用域贯穿调用与 OAuth&quot;">​</a></h3><p>2026-11-13T04:51:41Z · <strong>MERGED</strong> · main · <a href="https://github.com/openai/codex/pull/61257" target="_blank" rel="noreferrer">原始来源</a></p><p>同名服务按注册 scope 分开库存与状态；工具、资源及 OAuth 支持 environmentId，登录可指定环境。不传 selector 保留旧的按名称路由，不能据此宣称默认强隔离。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o3-·-codex-补齐-linux-网络沙箱旁路控制" tabindex="-1">O3 · Codex：补齐 Linux 网络沙箱旁路控制 <a class="header-anchor" href="#o3-·-codex-补齐-linux-网络沙箱旁路控制" aria-label="Permalink to &quot;O3 · Codex：补齐 Linux 网络沙箱旁路控制&quot;">​</a></h3><p>2026-11-13T04:51:02Z · <strong>MERGED</strong> · main · <a href="https://github.com/openai/codex/pull/61256" target="_blank" rel="noreferrer">原始来源</a></p><p>Restricted 与 ProxyRouted seccomp 模式禁止 request_key，防止其调用宿主 helper 绕过网络 namespace/proxy；VmSocketRestricted 未变。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o4-·-paperclip-供应商自行发起的-turn-契约" tabindex="-1">O4 · Paperclip：供应商自行发起的 turn 契约 <a class="header-anchor" href="#o4-·-paperclip-供应商自行发起的-turn-契约" aria-label="Permalink to &quot;O4 · Paperclip：供应商自行发起的 turn 契约&quot;">​</a></h3><p>2026-11-14T00:20:47Z · <strong>MERGED</strong> · master · <a href="https://github.com/paperclipai/paperclip/pull/21422" target="_blank" rel="noreferrer">原始来源</a></p><p>PRP 与 sidecar 协议声明 provider-started turn 的字段和命令，用于后台命令结束后由 Claude 自行续跑的场景。本 PR 只声明契约；行为栈仍须按各 PR 和发行逐项核验。它属于 controller/Runner 协议，不能直接当成 FCoP 同层替代。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o5-·-paperclip-恢复熔断覆盖已排队工作" tabindex="-1">O5 · Paperclip：恢复熔断覆盖已排队工作 <a class="header-anchor" href="#o5-·-paperclip-恢复熔断覆盖已排队工作" aria-label="Permalink to &quot;O5 · Paperclip：恢复熔断覆盖已排队工作&quot;">​</a></h3><p>2026-11-14T05:33:54Z · <strong>MERGED</strong> · master · <a href="https://github.com/paperclipai/paperclip/pull/21561" target="_blank" rel="noreferrer">原始来源</a></p><p>公司级自动运行熔断开启时，已经排队的自动 continuation/retry 也禁止启动；保留单次探测和半开限速。人的 Retry/请求不受此自动门禁阻挡。解决只禁止创建、却放行旧队列造成的恢复风暴。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o6-·-paperclip-服务账号连接与凭证归属" tabindex="-1">O6 · Paperclip：服务账号连接与凭证归属 <a class="header-anchor" href="#o6-·-paperclip-服务账号连接与凭证归属" aria-label="Permalink to &quot;O6 · Paperclip：服务账号连接与凭证归属&quot;">​</a></h3><p>2026-11-14T03:10:33Z · <strong>MERGED</strong> · master · <a href="https://github.com/paperclipai/paperclip/pull/21473" target="_blank" rel="noreferrer">原始来源</a></p><p>组织连接新增 MCP OAuth client_credentials，可用逐连接签名密钥或 client secret；私钥留在公司 vault，签入时固定 issuer/token endpoint。上游实现采用既有扩展，不是本轮新制定的 MCP 核心授权规范。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o7-·-paperclip-不确定回执可据服务端证据结算" tabindex="-1">O7 · Paperclip：不确定回执可据服务端证据结算 <a class="header-anchor" href="#o7-·-paperclip-不确定回执可据服务端证据结算" aria-label="Permalink to &quot;O7 · Paperclip：不确定回执可据服务端证据结算&quot;">​</a></h3><p>2026-11-14T00:45:52Z · <strong>MERGED</strong> · master · <a href="https://github.com/paperclipai/paperclip/pull/21522" target="_blank" rel="noreferrer">原始来源</a></p><p>客户端超时而服务端已提交时，unknown 回执曾永久阻挡后续同 operation 的写入。现在用服务端最终记录结算；确实未知时仍保留 fence。应研究恢复证据的权威性，而不是遇到超时直接重试。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o8-·-paperclip-千-agent-是测量与规划目标" tabindex="-1">O8 · Paperclip：千 Agent 是测量与规划目标 <a class="header-anchor" href="#o8-·-paperclip-千-agent-是测量与规划目标" aria-label="Permalink to &quot;O8 · Paperclip：千 Agent 是测量与规划目标&quot;">​</a></h3><p>2026-11-13T22:06:41Z · <strong>MERGED</strong> · master · <a href="https://github.com/paperclipai/paperclip/pull/21418" target="_blank" rel="noreferrer">原始来源</a></p><p>新增负载模型与分阶段规划。上游描述约 50 并发时，逐 delta 事务让数据库与认证连接池互相挤压；1000 并发是目标，不能写成已达到。学习价值高、竞争风险高，雷达保持重点，扩展性成熟度保留审慎判断。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o9-·-openhands-等待模型期间暂停也必须落盘" tabindex="-1">O9 · OpenHands：等待模型期间暂停也必须落盘 <a class="header-anchor" href="#o9-·-openhands-等待模型期间暂停也必须落盘" aria-label="Permalink to &quot;O9 · OpenHands：等待模型期间暂停也必须落盘&quot;">​</a></h3><p>2026-11-13T21:15:58Z · <strong>MERGED</strong> · main · <a href="https://github.com/OpenHands/software-agent-sdk/pull/5776" target="_blank" rel="noreferrer">原始来源</a></p><p>LLM I/O 释放锁时也释放 deferred-save 嵌套，使并发 pause 立即自动保存；返回后恢复嵌套。此前内存已暂停、磁盘仍 running，崩溃可能丢失暂停。维护者 enyst 仍直接参与本 PR。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o10-·-openhands-mcp-协商与-oauth-故障分开" tabindex="-1">O10 · OpenHands：MCP 协商与 OAuth 故障分开 <a class="header-anchor" href="#o10-·-openhands-mcp-协商与-oauth-故障分开" aria-label="Permalink to &quot;O10 · OpenHands：MCP 协商与 OAuth 故障分开&quot;">​</a></h3><p>2026-11-13T21:06:24Z · <strong>MERGED</strong> · main · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6794" target="_blank" rel="noreferrer">原始来源</a></p><p>启用 MCP 协议自动协商；PR 明确 OAuth callback redirect 的另一问题仍由 #6808 跟踪，不能写成一并解决。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o11-·-github-mcp-按工具过滤技能、按需隐藏-secret" tabindex="-1">O11 · GitHub MCP：按工具过滤技能、按需隐藏 secret <a class="header-anchor" href="#o11-·-github-mcp-按工具过滤技能、按需隐藏-secret" aria-label="Permalink to &quot;O11 · GitHub MCP：按工具过滤技能、按需隐藏 secret&quot;">​</a></h3><p>2026-11-13T12:57:41Z · <strong>MERGED</strong> · main · <a href="https://github.com/github/github-mcp-server/pull/3685" target="_blank" rel="noreferrer">原始来源</a></p><p>可选 Skills over MCP，18 个工作流按连接可用工具过滤，启用后替代 server instructions。另 #3838 为 secret scanning 工具添加 hide_secret；只有 true 才请求 API 排除 secret，默认未改变。技能发现与动作授权仍是不同控制面。 服务端与客户端均需 feature flag；安装客户端的 consent UX 与远端部署另有交付边界，不能因 server PR 合入即宣称全链已发行。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o12-·-orkas-延迟确认不能盖过较新的收件人状态" tabindex="-1">O12 · Orkas：延迟确认不能盖过较新的收件人状态 <a class="header-anchor" href="#o12-·-orkas-延迟确认不能盖过较新的收件人状态" aria-label="Permalink to &quot;O12 · Orkas：延迟确认不能盖过较新的收件人状态&quot;">​</a></h3><p>2026-11-14T02:13:46Z · <strong>MERGED</strong> · main · <a href="https://github.com/Orkas-AI/Orkas/pull/213" target="_blank" rel="noreferrer">原始来源</a></p><p>Commander 写入确认结束后，立即重算较新的权威 floor，保留 revision、导航归属和失败/被替代写入边界。上游有真实 macOS Electron 路程与负对照；无 Windows/Linux 实机 GUI 或模型计费验证。学习价值中高、风险中，增加交互路由正确性观察。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o13-·-eigent-插件导入边界与并发工作区修复" tabindex="-1">O13 · Eigent：插件导入边界与并发工作区修复 <a class="header-anchor" href="#o13-·-eigent-插件导入边界与并发工作区修复" aria-label="Permalink to &quot;O13 · Eigent：插件导入边界与并发工作区修复&quot;">​</a></h3><p>2026-11-13T09:46:14Z · <strong>MERGED</strong> · main · <a href="https://github.com/eigent-ai/eigent/pull/2192" target="_blank" rel="noreferrer">原始来源</a></p><p>插件源拒绝系统、凭证、他人 home 与磁盘根目录；此前通用文件访问范围扩至多盘时漏了此处。另 #2194 将会读取全 worktree 元数据的 Git 命令按仓库串行，修复同时启动两个 Session 的半写元数据竞态。学习价值高、风险中高，增加共享仓库并发验收观察。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o14-·-beads-派生依赖状态也要保留责任人" tabindex="-1">O14 · Beads：派生依赖状态也要保留责任人 <a class="header-anchor" href="#o14-·-beads-派生依赖状态也要保留责任人" aria-label="Permalink to &quot;O14 · Beads：派生依赖状态也要保留责任人&quot;">​</a></h3><p>2026-11-13T19:22:14Z · <strong>MERGED</strong> · main · <a href="https://github.com/gastownhall/beads/pull/8432" target="_blank" rel="noreferrer">原始来源</a></p><p>close/reopen/依赖变更引起的派生 is_blocked journal 过去 actor 为空；现在显式传入原请求 actor。多 Agent 责任链须覆盖派生事件。学习价值高、风险中，继续作为任务/依赖工件协调参考。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o15-·-browser-use-默认增加同模型事后判断" tabindex="-1">O15 · browser-use：默认增加同模型事后判断 <a class="header-anchor" href="#o15-·-browser-use-默认增加同模型事后判断" aria-label="Permalink to &quot;O15 · browser-use：默认增加同模型事后判断&quot;">​</a></h3><p>2026-11-14T04:52:12Z · <strong>MERGED</strong> · main · <a href="https://github.com/browser-use/browser-use/pull/6398" target="_blank" rel="noreferrer">原始来源</a></p><p>每次执行过步骤的 run 增加一次同模型 low-effort judge，返回 success/失败原因/注入标记/gotchas，计入 token 与成本；可 judge=False。输入脱敏、有长度边界。这是主分支新行为，不能称为独立验收，也未证明发布包已包含。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o16-·-semantic-kernel-校验与写入必须使用同一最终路径" tabindex="-1">O16 · Semantic Kernel：校验与写入必须使用同一最终路径 <a class="header-anchor" href="#o16-·-semantic-kernel-校验与写入必须使用同一最终路径" aria-label="Permalink to &quot;O16 · Semantic Kernel：校验与写入必须使用同一最终路径&quot;">​</a></h3><p>2026-11-13T16:16:43Z · <strong>MERGED</strong> · main · <a href="https://github.com/microsoft/semantic-kernel/pull/14791" target="_blank" rel="noreferrer">原始来源</a></p><p>SessionsPythonTool 过去只 resolve 文件夹再拼文件名，文件名是 symlink 时可能写出允许目录。现在 realpath 解析整个路径并返回同一写入目标；未配置 allowed_download_directories 时行为不变。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o17-·-codex-0-169-正式交付信任与计划交接修复" tabindex="-1">O17 · Codex 0.169 正式交付信任与计划交接修复 <a class="header-anchor" href="#o17-·-codex-0-169-正式交付信任与计划交接修复" aria-label="Permalink to &quot;O17 · Codex 0.169 正式交付信任与计划交接修复&quot;">​</a></h3><p>2026-11-13T08:37:05Z · <strong>RELEASED</strong> · <a href="https://github.com/openai/codex/releases/tag/rust-v0.169.0" target="_blank" rel="noreferrer">原始来源</a></p><p>codex exec 在未信任目录继续禁用项目配置和 MCP；清空上下文并实现时携带完整批准计划，交接失败保留原会话；延迟 abort 不再打断后续 turn。这些已发行修复与主分支新增须分开。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o18-·-agents-js-0-22-审批与-checkpoint-兼容性进入发行" tabindex="-1">O18 · Agents JS 0.22：审批与 checkpoint 兼容性进入发行 <a class="header-anchor" href="#o18-·-agents-js-0-22-审批与-checkpoint-兼容性进入发行" aria-label="Permalink to &quot;O18 · Agents JS 0.22：审批与 checkpoint 兼容性进入发行&quot;">​</a></h3><p>2026-11-12T23:57:37Z · <strong>RELEASED</strong> · <a href="https://github.com/openai/openai-agents-js/releases/tag/%40openai/agents-core%400.22.0" target="_blank" rel="noreferrer">原始来源</a></p><p>发布包含待工具审批时推迟自动 compaction、运行中 Docker 资源按容器用户权限落地及复制限制；兼容状态保留 schema 1.23，较丰富 metadata/nested runs 使用 1.24，并有需收窄的类型变更。是升级与恢复兼容性议题，未本地迁移实测。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o19-·-claude-code-2-1-325-恢复、工作目录与子-agent-模型修复" tabindex="-1">O19 · Claude Code 2.1.325：恢复、工作目录与子 Agent 模型修复 <a class="header-anchor" href="#o19-·-claude-code-2-1-325-恢复、工作目录与子-agent-模型修复" aria-label="Permalink to &quot;O19 · Claude Code 2.1.325：恢复、工作目录与子 Agent 模型修复&quot;">​</a></h3><p>2026-11-13T20:40:01Z · <strong>RELEASED</strong> · <a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.325" target="_blank" rel="noreferrer">原始来源</a></p><p>正式修复非正常退出后恢复丢最近 turn、工作目录删除后 shell 意外回 launch directory、子 Agent 独立模型被 plan 模型替换及用主会话窗口预算读文件/MCP 的问题；还声明 zstd 解码安全修复，未核查具体漏洞细节。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o20-·-agentlas-os-1-2-97-hook-代码来源固定到安装引擎" tabindex="-1">O20 · Agentlas OS 1.2.97：hook 代码来源固定到安装引擎 <a class="header-anchor" href="#o20-·-agentlas-os-1-2-97-hook-代码来源固定到安装引擎" aria-label="Permalink to &quot;O20 · Agentlas OS 1.2.97：hook 代码来源固定到安装引擎&quot;">​</a></h3><p>2026-11-13T05:38:16Z · <strong>RELEASED</strong> · <a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/os-v1.2.97" target="_blank" rel="noreferrer">原始来源</a></p><p>正式安全发行：memory/checkpoint/ontology/Windows launcher 等不再先从工作项目目录找执行代码，防止 clone/共享目录替换 Agentlas 实现。上游要求同时升级插件并重启宿主加载新 hooks；旧 v1.2 通道另有兼容发行。学习价值高、风险中，提升安装链与 hook 信任观察。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o21-·-langgraph-1-2-22-子图独立线程仍可被父流观察" tabindex="-1">O21 · LangGraph 1.2.22：子图独立线程仍可被父流观察 <a class="header-anchor" href="#o21-·-langgraph-1-2-22-子图独立线程仍可被父流观察" aria-label="Permalink to &quot;O21 · LangGraph 1.2.22：子图独立线程仍可被父流观察&quot;">​</a></h3><p>2026-11-14T01:43:55Z · <strong>RELEASED</strong> · <a href="https://github.com/langchain-ai/langgraph/releases/tag/1.2.22" target="_blank" rel="noreferrer">原始来源</a></p><p>正式版本包含 #9698：独立 thread 的 child graph 向启用 subgraph streaming 的 caller 暴露流；可研究多 Agent 子任务可见性，但不能仅据此推成完整交接/恢复协议。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o22-·-langfuse-4-79-mcp-读取也进入审计" tabindex="-1">O22 · Langfuse 4.79：MCP 读取也进入审计 <a class="header-anchor" href="#o22-·-langfuse-4-79-mcp-读取也进入审计" aria-label="Permalink to &quot;O22 · Langfuse 4.79：MCP 读取也进入审计&quot;">​</a></h3><p>2026-11-12T09:40:45Z · <strong>RELEASED</strong> · <a href="https://github.com/langfuse/langfuse/releases/tag/v4.79.0" target="_blank" rel="noreferrer">原始来源</a></p><p>发行包含 MCP 工具 read-access 审计事件，以及 self-hosted enterprise 的审计暂存/转发。企业功能边界须按部署与许可单独核对；未证明所有开源部署都可用。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o23-·-赵越-模型注册、独立审查集合与本地技能发现" tabindex="-1">O23 · 赵越：模型注册、独立审查集合与本地技能发现 <a class="header-anchor" href="#o23-·-赵越-模型注册、独立审查集合与本地技能发现" aria-label="Permalink to &quot;O23 · 赵越：模型注册、独立审查集合与本地技能发现&quot;">​</a></h3><p>2026-11-14T03:56:38Z · <strong>COMMITTED</strong> · <a href="https://github.com/yzhao062/anywhere-agents/commit/94034fbfea6e1a09bc7acaa3e9fe5d42a8ecc273" target="_blank" rel="noreferrer">原始来源</a></p><p>11 月 11—14 日直接提交：注册表记录 requested/actual 模型与 effort；/vet all 选择协调者之外的三个审查者；后续移除 Copilot reviewer；项目本地 skills 链入 .agents/skills，并避免改动非自有链接。相关 agent-config 有镜像，不重复计事件。上游小样本速度/成本结果不能泛化成模型排名。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o24-·-anthropic-安全评估需要校准评分者与完整场景" tabindex="-1">O24 · Anthropic：安全评估需要校准评分者与完整场景 <a class="header-anchor" href="#o24-·-anthropic-安全评估需要校准评分者与完整场景" aria-label="Permalink to &quot;O24 · Anthropic：安全评估需要校准评分者与完整场景&quot;">​</a></h3><p>2026-11-13 · <strong>PUBLISHED</strong> · <a href="https://www.anthropic.com/research/building-strong-safety-evaluations" target="_blank" rel="noreferrer">原始来源</a></p><p>新文建议先定义测量目标，区分观察与因果设计；用多轮情境而非只算拒绝率，同时衡量恶意配合与良性误拒。评分者须对照人工标签校准，故障明确报错；报告模型、harness、grader 版本和统计不确定性。是方法建议，上游分数不代表本地实测。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o25-·-mcp-规范改为六个月发行节奏" tabindex="-1">O25 · MCP：规范改为六个月发行节奏 <a class="header-anchor" href="#o25-·-mcp-规范改为六个月发行节奏" aria-label="Permalink to &quot;O25 · MCP：规范改为六个月发行节奏&quot;">​</a></h3><p>2026-11-11T19:27:18Z · <strong>MERGED</strong> · <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/3541" target="_blank" rel="noreferrer">原始来源</a></p><p>合入发行周期公告：依据 SEP-3398 采用六个月规范节奏，下一目标 2027-03-30，并列提案、SDK beta 和 freeze 里程碑。属于发行治理变化，目标日期不等于协议已发行或 SDK 已实现。</p><p>处置：持续观察/资料留存；尚未本地安装或实验。</p><h3 id="o26-·-codex-整棵-agent-树暂停与恢复" tabindex="-1">O26 · Codex：整棵 Agent 树暂停与恢复 <a class="header-anchor" href="#o26-·-codex-整棵-agent-树暂停与恢复" aria-label="Permalink to &quot;O26 · Codex：整棵 Agent 树暂停与恢复&quot;">​</a></h3><p>2026-11-12T22:43:44Z · <strong>MERGED</strong> · main · <a href="https://github.com/openai/codex/pull/61198" target="_blank" rel="noreferrer">原始来源</a></p><p>持久化终态子结果后才允许 suspend 成功；返回未完成 root/具名 V2 child turn 与 pending wake，恢复后代但不启动模型。失败或未确认写入必须报告，适用于持久树，未证明任意跨宿主迁移。</p><h3 id="o27-·-codex-spiffe-工作负载身份" tabindex="-1">O27 · Codex：SPIFFE 工作负载身份 <a class="header-anchor" href="#o27-·-codex-spiffe-工作负载身份" aria-label="Permalink to &quot;O27 · Codex：SPIFFE 工作负载身份&quot;">​</a></h3><p>2026-11-12T23:54:23Z · <strong>MERGED</strong> · main · <a href="https://github.com/openai/codex/pull/61207" target="_blank" rel="noreferrer">原始来源</a></p><p>Unix Workload API 的 JWT-SVID 可用于既有 token exchange，默认仍为文件；拒绝歧义或 subject/audience 不符，签名与期限验证仍由 token endpoint 负责。</p><h3 id="o28-·-paradev-浏览器域与-token-身份分开" tabindex="-1">O28 · Paradev：浏览器域与 token 身份分开 <a class="header-anchor" href="#o28-·-paradev-浏览器域与-token-身份分开" aria-label="Permalink to &quot;O28 · Paradev：浏览器域与 token 身份分开&quot;">​</a></h3><p>2026-11-12T23:49:14Z · <strong>MERGED</strong> · main · <a href="https://github.com/ParadevAI/Paradev/pull/9687" target="_blank" rel="noreferrer">原始来源</a></p><p>可选浏览器 API origin 保留 api.superset.sh token identity 与 canonical MCP audience；未改变生产域或重定向。预览验证不等于正式迁移完成。学习价值高、风险中高，跟踪授权兼容。</p><h3 id="o29-·-orca-控制连接在线不代表手机可接入" tabindex="-1">O29 · Orca：控制连接在线不代表手机可接入 <a class="header-anchor" href="#o29-·-orca-控制连接在线不代表手机可接入" aria-label="Permalink to &quot;O29 · Orca：控制连接在线不代表手机可接入&quot;">​</a></h3><p>2026-11-13T23:10:06Z · <strong>MERGED</strong> · main · <a href="https://github.com/stablyai/orca/pull/41991" target="_blank" rel="noreferrer">原始来源</a></p><p>手机 data attach 连续失败时，桌面重新向 director 请求分配，修复控制 socket 存活但数据面失败只能重启的情况。学习价值高、风险中高，手机验收应包含真实 attach 与恢复。</p><h2 id="研究分析" tabindex="-1">研究分析 <a class="header-anchor" href="#研究分析" aria-label="Permalink to &quot;研究分析&quot;">​</a></h2><h3 id="a1-·-动作授权需要绑定环境、凭证与代码来源" tabindex="-1">A1 · 动作授权需要绑定环境、凭证与代码来源 <a class="header-anchor" href="#a1-·-动作授权需要绑定环境、凭证与代码来源" aria-label="Permalink to &quot;A1 · 动作授权需要绑定环境、凭证与代码来源&quot;">​</a></h3><p>O2、O3、O6、O11、O13、O16、O20、O27、O28</p><p>证据支持：多个实现分别补充环境 selector、机器凭证归属、最小化 secret 暴露与 hook/import/path 边界。待验证：CodeFlowMu 在执行时是否同时绑定岗位主体、组织、连接环境和可信代码。实验候选：同名服务跨环境调用、项目同名模块劫持、symlink 写入；适配层/Runtime 议题，不能直接推成 FCoP 内核要求。</p><h3 id="a2-·-恢复要结算真实结果-暂停也要耐久化" tabindex="-1">A2 · 恢复要结算真实结果，暂停也要耐久化 <a class="header-anchor" href="#a2-·-恢复要结算真实结果-暂停也要耐久化" aria-label="Permalink to &quot;A2 · 恢复要结算真实结果，暂停也要耐久化&quot;">​</a></h3><p>O1、O5、O7、O9、O12、O17、O19、O26、O29</p><p>证据支持：提交、回执、暂停与重试各有不同失败窗口；Paperclip 的 queued brake 与 unknown receipt 修复给出具体反例。待验证：将 FCoP 工件收据与 Runtime 操作结算映射能否减少重复副作用和永久 fence。实验候选：提交后断线、模型等待中暂停再断电、乱序确认；须保留未知结果，不能自动等同失败。</p><h3 id="a3-·-协议比较要沿真实连接链拆层" tabindex="-1">A3 · 协议比较要沿真实连接链拆层 <a class="header-anchor" href="#a3-·-协议比较要沿真实连接链拆层" aria-label="Permalink to &quot;A3 · 协议比较要沿真实连接链拆层&quot;">​</a></h3><p>O2、O4、O6、O10、O11、O21、O25</p><p>证据支持：MCP 协商/工具技能、OAuth 机器身份、PRP controller/Runner turn 各解决不同层面问题。另 MCP #3541 已合入六个月规范周期与 2027-03-30 目标公告，目标不等于新协议已发布。体验候选：PRP 契约及 MCP Skills，在固定版本、License/依赖核对后体验；FCoP 文件/工件协调可互补，当前没有替换内核的依据。</p><h3 id="a4-·-验收本身也需要治理与独立证据" tabindex="-1">A4 · 验收本身也需要治理与独立证据 <a class="header-anchor" href="#a4-·-验收本身也需要治理与独立证据" aria-label="Permalink to &quot;A4 · 验收本身也需要治理与独立证据&quot;">​</a></h3><p>O14、O15、O23、O24</p><p>证据支持：Beads 补派生事件 actor，browser-use 使用同模型事后 judge，赵越框架记录实际模型并排除协调者参与审查。Anthropic 新文要求校准 grader、预先定义指标、报告不确定性；同模型 judge 不能叫独立验收。实验候选：用隐藏结果检查同模型、异模型与规则验收的一致性，成本与漏判率均记录。</p><h3 id="a5-·-竞品成熟度需由故障反例和交付边界重估" tabindex="-1">A5 · 竞品成熟度需由故障反例和交付边界重估 <a class="header-anchor" href="#a5-·-竞品成熟度需由故障反例和交付边界重估" aria-label="Permalink to &quot;A5 · 竞品成熟度需由故障反例和交付边界重估&quot;">​</a></h3><p>O5、O7、O8、O12、O13、O20、O22</p><p>Paperclip 学习与竞争风险均高，但千并发仍属目标；Eigent 的 Git Space 并发修复是团队交付直接证据；Orkas 的 macOS 负对照比测试数量更有价值，但平台覆盖有限；Agentlas 的更新通道与 hook 信任须一起看。体验候选按这四条故障路径选择，尚未安装。未核实新的商业/License 结构性变化，本轮不据此调整商业判断。</p><h2 id="跨项目共振与互动议题" tabindex="-1">跨项目共振与互动议题 <a class="header-anchor" href="#跨项目共振与互动议题" aria-label="Permalink to &quot;跨项目共振与互动议题&quot;">​</a></h2><p>O1/O7/O9/O14 的共振是证据必须覆盖真实状态、未知结果与派生动作；O2/O6/O11/O20 表明身份、连接、技能发现与可信执行应分别验收。值得向上游讨论的具体问题：Paperclip 以什么服务端记录结算 unknown receipt，如何覆盖跨运行重复副作用；GitHub MCP 技能可见性变化后，动作授权是否独立重查；browser-use 同模型 judge 与独立隐藏验收的分歧如何测量。这里只记录技术切入点，未发送评论。</p><h2 id="双源核查与覆盖说明" tabindex="-1">双源核查与覆盖说明 <a class="header-anchor" href="#双源核查与覆盖说明" aria-label="Permalink to &quot;双源核查与覆盖说明&quot;">​</a></h2><p>本轮实际执行起点 2026-11-14 14:55:09（Asia/Shanghai）。最新 main Registry 47 人。最近成功轮 2026-11-11T022417Z；11 月 12 日执行中断、13 日无成功记录，按各来源成功基线补查，不补造漏跑日期日报。88 个原始仓库入口 commits/issues/releases 初始查询 264 次；满 100 页与历史积压未穷尽，release 仅前 10 条，均保留覆盖限制。TSA 返回不可访问，Superset 原入口迁移，Paradev 另行补查不擅自改名。已核对 Cursor changelog、Anthropic 工程页、赵越主页与部分作者检索；未穷尽全部 47 人 X/回复、Discussion/Roadmap、License 历史与全部源码，不能写成无变化。上游测试和案例均未本地复现；实验、文章、开发评审、外部互动均为 0。</p><p>非 GitHub 核查入口：<a href="https://cursor.com/changelog" target="_blank" rel="noreferrer">Cursor</a>、<a href="https://www.anthropic.com/engineering" target="_blank" rel="noreferrer">Anthropic</a>、<a href="https://yzhao062.github.io/" target="_blank" rel="noreferrer">Yue Zhao</a>。</p>',136)])])}const g=a(n,[["render",p]]);export{u as __pageData,g as default};
